class Solution:
    def calendarTwoBookings(self, bookings: list[list[int]]) -> list[bool]:
        accepted = []
        result = []
        for start, end in bookings:
            events = []
            for a, b in accepted:
                events.append((a, 1))
                events.append((b, -1))
            events.append((start, 1))
            events.append((end, -1))
            events.sort(key=lambda x: (x[0], x[1]))
            active = 0
            ok = True
            for _, delta in events:
                active += delta
                if active >= 3:
                    ok = False
                    break
            result.append(ok)
            if ok:
                accepted.append([start, end])
        return result

