class Solution:
    def calendarTwoBookings(self, bookings: list[list[int]]) -> list[bool]:
        accepted = []
        overlaps = []
        result = []
        for start, end in bookings:
            ok = True
            for a, b in overlaps:
                if start < b and a < end:
                    ok = False
                    break
            result.append(ok)
            if not ok:
                continue
            for a, b in accepted:
                left = max(start, a)
                right = min(end, b)
                if left < right:
                    overlaps.append([left, right])
            accepted.append([start, end])
        return result

