class Solution:
    def calendarTwoBookings(self, bookings: list[list[int]]) -> list[bool]:
        from collections import defaultdict
        diff = defaultdict(int)
        result = []
        for start, end in bookings:
            diff[start] += 1
            diff[end] -= 1
            active = 0
            ok = True
            for point in sorted(diff):
                active += diff[point]
                if active >= 3:
                    ok = False
                    break
            if not ok:
                diff[start] -= 1
                diff[end] += 1
                if diff[start] == 0:
                    del diff[start]
                if diff[end] == 0:
                    del diff[end]
            result.append(ok)
        return result

